def is_palindrome(text):
    clean_chars = []
    for char in text:
        if char.isalnum():
            clean_chars.append(char.lower())
    clean_string = "".join(clean_chars)

    reversed_chars = []
    for i in range(len(clean_string) - 1, -1, -1):
        reversed_chars.append(clean_string[i])
    reversed_string = "".join(reversed_chars)

    return clean_string == reversed_string

def find_palindromes(word_list):
    possible_palindromes = []
    for word in word_list:
        if len(word) > 1:
            possible_palindromes.append(word)

    palindromes = []
    for word in possible_palindromes:
        if is_palindrome(word):
            palindromes.append(word)

    uppercase_palindromes = []
    for p in palindromes:
        uppercase_palindromes.append(p.upper())

    palindrome_lengths = []
    for p in palindromes:
        palindrome_lengths.append(len(p))

    unique_lengths = sorted(list(set(palindrome_lengths)))

    long_palindromes = []
    for p in palindromes:
        if len(p) > 3:
            long_palindromes.append(p)

    initials = []
    for p in long_palindromes:
        initials.append(p[0])

    return palindromes, uppercase_palindromes, unique_lengths, initials

