def simple_calculator(num1, operator, num2):
    operators = ['+', '-', '*', '/']
    if operator not in operators:
        return 'Error'

    if operator == '/' and num2 == 0:
        return 'Error'

    results_map = {
        '+': num1 + num2,
        '-': num1 - num2,
        '*': num1 * num2,
        '/': num1 / num2
    }

    return results_map[operator]

def process_calculations(calculations):
    processed_results = [
        simple_calculator(calc[0], calc[1], calc[2]) 
        for calc in calculations
    ]

    successful_results = [
        result for result in processed_results if result != 'Error'
    ]

    error_flags = [
        'Error' for result in processed_results if result == 'Error'
    ]

    operations_performed = [
        f"{calc[0]} {calc[1]} {calc[2]}" 
        for calc in calculations if simple_calculator(calc[0], calc[1], calc[2]) != 'Error'
    ]

    failed_operations = [
        f"{calc[0]} {calc[1]} {calc[2]}" 
        for calc in calculations if simple_calculator(calc[0], calc[1], calc[2]) == 'Error'
    ]

    return successful_results, error_flags, operations_performed, failed_operations

