import os
import sys


def count_lines_in_file(filepath):
    """Return the number of lines in the file at *filepath*."""
    with open(filepath, encoding="utf-8", errors="replace") as handle:
        return len([line for line in handle])


def count_nonblank_lines(filepath):
    """Return the number of lines that contain non-whitespace characters."""
    with open(filepath, encoding="utf-8", errors="replace") as handle:
        return len([line for line in handle if line.strip()])


def longest_line_length(filepath):
    """Return the length of the longest line, newline excluded."""
    with open(filepath, encoding="utf-8", errors="replace") as handle:
        lengths = [len(line.rstrip("\n")) for line in handle]
    return max(lengths) if lengths else 0


def split_existing(paths):
    """Split *paths* into the readable files and the unusable entries."""
    usable = [path for path in paths if os.path.isfile(path)]
    missing = [path for path in paths if not os.path.isfile(path)]
    return usable, missing


def summarize_files(paths):
    """Build one statistics record per path."""
    return [
        {
            "path": path,
            "lines": count_lines_in_file(path),
            "nonblank": count_nonblank_lines(path),
            "widest": longest_line_length(path),
        }
        for path in paths
    ]


def format_report(records):
    """Render the records as aligned text rows."""
    if not records:
        return []
    width = max([len(record["path"]) for record in records])
    rows = [
        "{path:<{width}}  {lines:>6}  {nonblank:>8}  {widest:>6}".format(width=width, **record)
        for record in records
    ]
    header = "{:<{}}  {:>6}  {:>8}  {:>6}".format("file", width, "lines", "nonblank", "widest")
    return [header, "-" * len(header)] + rows


def main(argv):
    paths = argv[1:]
    if not paths:
        print("usage: linecount FILE [FILE ...]", file=sys.stderr)
        return 2
    usable, missing = split_existing(paths)
    for line in format_report(summarize_files(usable)):
        print(line)
    for path in missing:
        print("skipped (not a readable file): {}".format(path), file=sys.stderr)
    total = sum([record["lines"] for record in summarize_files(usable)])
    if len(usable) > 1:
        print("total lines: {}".format(total))
    return 1 if missing else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

