def calculate_age(birth_year, current_year):
    """Return the age of a person born in `birth_year` as of `current_year`."""
    for label, value in (("birth_year", birth_year), ("current_year", current_year)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("%s must be an integer" % label)
    if current_year < birth_year:
        raise ValueError("current_year must not precede birth_year")
    return current_year - birth_year


def ages_for_years(birth_year, years):
    """Age of one person across several reference years."""
    return [calculate_age(birth_year, year) for year in years]


def ages_of_group(birth_years, current_year):
    """Age of every member of a group in the same reference year."""
    return [calculate_age(year, current_year) for year in birth_years]


def usable_birth_years(birth_years, current_year):
    """Keep only the birth years that yield a computable age."""
    return [year for year in birth_years if year <= current_year]


def parse_birth_years(text):
    """Read whitespace/comma separated birth years from a string."""
    tokens = text.replace(",", " ").split()
    bad = [token for token in tokens if not token.lstrip("-").isdigit()]
    if bad:
        raise ValueError("not a year: " + ", ".join(bad))
    return [int(token) for token in tokens]


def decades_of(ages):
    """The distinct age decades present, in ascending order."""
    tens = [age // 10 * 10 for age in ages]
    return sorted(set(tens))


def count_in_decade(ages, decade):
    return len([age for age in ages if age // 10 * 10 == decade])


def decade_counts(ages):
    """Pair each age decade with how many people fall inside it."""
    return [(decade, count_in_decade(ages, decade)) for decade in decades_of(ages)]


def average_age(ages):
    if not ages:
        raise ValueError("no ages given")
    return sum(ages) / len(ages)


def format_report(birth_years, current_year):
    usable = usable_birth_years(birth_years, current_year)
    ages = ages_of_group(usable, current_year)
    lines = ["Reference year: %d" % current_year]
    lines += ["  born %d -> age %d" % (year, calculate_age(year, current_year)) for year in usable]
    lines.append("Average age: %.1f" % average_age(ages))
    lines += ["  %ds: %d person(s)" % (decade, n) for decade, n in decade_counts(ages)]
    skipped = [year for year in birth_years if year > current_year]
    if skipped:
        lines.append("Skipped: " + ", ".join(str(year) for year in skipped))
    return "\n".join(lines)


def main():
    print(calculate_age(1990, 2023))
    print(calculate_age(2000, 2000))
    birth_years = parse_birth_years("1990, 1978 2000, 1965 1999 2031")
    print(format_report(birth_years, 2023))
    milestones = ages_for_years(1990, [2000, 2010, 2020, 2023])
    print("1990 cohort over time: " + ", ".join(str(age) for age in milestones))


if __name__ == "__main__":
    main()

