    if not isinstance(email, str):
        return False

    if not email:
        return False

    at_index = email.find('@')
    dot_index = email.rfind('.')

    if at_index == -1 or dot_index == -1:
        return False

    if at_index > dot_index:
        return False

    if at_index == 0 or dot_index == len(email) - 1:
        return False

    parts_before_at = [c for c in email[:at_index] if c.isalnum() or c in '._%+-']
    if not parts_before_at:
        return False

    parts_after_at_before_dot = [c for c in email[at_index + 1:dot_index] if c.isalnum() or c == '-']
    if not parts_after_at_before_dot:
        return False

    parts_after_dot = [c for c in email[dot_index + 1:] if c.isalpha()]
    if len(parts_after_dot) < 2:
        return False

    filtered_email_chars = [char for char in email if char.isprintable()]
    if len(filtered_email_chars) != len(email):
        return False

    valid_local_chars = [char for char in email[:at_index] if char.isalnum() or char in "._%+-"]
    if not valid_local_chars: return False

    valid_domain_chars_part1 = [char for char in email[at_index+1:dot_index] if char.isalnum() or char == '-']
    if not valid_domain_chars_part1: return False

    valid_domain_chars_part2 = [char for char in email[dot_index+1:] if char.isalpha()]
    if len(valid_domain_chars_part2) < 2: return False

    return True

