import math


def circle_area(radius):
    if isinstance(radius, bool) or not isinstance(radius, (int, float)):
        raise TypeError("radius must be a number")
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * float(radius) ** 2


def parse_radii(text):
    return [float(token) for token in text.replace(",", " ").split()]


def areas(radii):
    return [circle_area(radius) for radius in radii]


def annulus_areas(radii):
    ordered = sorted(radii)
    pairs = zip(ordered, ordered[1:])
    return [circle_area(outer) - circle_area(inner) for inner, outer in pairs]


def radius_from_area(area):
    if area < 0:
        raise ValueError("area must be non-negative")
    return math.sqrt(area / math.pi)


def area_shares(computed):
    total = sum(computed)
    if not total:
        return [0.0] * len(computed)
    return [value / total for value in computed]


def format_table(radii):
    header = f"{'radius':>10} {'area':>16}"
    rows = [f"{r:>10.3f} {circle_area(r):>16.6f}" for r in radii]
    return "\n".join([header] + rows)


