import math


def distance_2d(x1, y1, x2, y2):
    """Euclidean distance between (x1, y1) and (x2, y2)."""
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)


def parse_points(lines):
    """Turn 'x,y' text lines into a list of (x, y) float pairs."""
    cleaned = [line.strip() for line in lines if line.strip()]
    pairs = [text.split(",") for text in cleaned]
    return [(float(a), float(b)) for a, b in pairs]


def distances_from(point, points):
    """Distances from one point to every point in the list."""
    x0, y0 = point
    return [distance_2d(x0, y0, x, y) for x, y in points]


def distance_matrix(points):
    """Full matrix of pairwise distances."""
    return [distances_from(point, points) for point in points]


def path_length(points):
    """Total length of the polyline through the given points."""
    steps = [distance_2d(*points[i], *points[i + 1]) for i in range(len(points) - 1)]
    return math.fsum(steps)


def nearest_neighbour(points, index):
    """Index of the point closest to points[index] (excluding itself)."""
    x0, y0 = points[index]
    candidates = [(distance_2d(x0, y0, x, y), i) for i, (x, y) in enumerate(points) if i != index]
    return min(candidates)[1]


def points_within(points, cx, cy, radius):
    """Points lying inside (or on) the circle of the given radius."""
    return [(x, y) for x, y in points if distance_2d(cx, cy, x, y) <= radius]


def centroid(points):
    xs = [x for x, _ in points]
    ys = [y for _, y in points]
    return math.fsum(xs) / len(points), math.fsum(ys) / len(points)


def format_row(row):
    """Render one matrix row as aligned numbers."""
    cells = ["{:7.3f}".format(value) for value in row]
    return " ".join(cells)


def format_matrix(matrix):
    """Render a distance matrix as aligned text rows."""
    rows = [format_row(row) for row in matrix]
    return "\n".join(rows)


def label_points(points):
    """Short readable labels for a list of points."""
    return ["({:g}, {:g})".format(x, y) for x, y in points]


def main():
    raw = ["0,0", "3,4", "1,1", " ", "-2,5", "6,-1"]
    points = parse_points(raw)

    print("distance_2d(0, 0, 3, 4) =", distance_2d(0, 0, 3, 4))
    print("distance_2d(1, 1, 1, 1) =", distance_2d(1, 1, 1, 1))

    print("\nPairwise distances:")
    print(format_matrix(distance_matrix(points)))

    print("\nPath length through all points: {:.3f}".format(path_length(points)))

    labels = label_points(points)
    neighbours = [labels[nearest_neighbour(points, i)] for i in range(len(points))]
    for label, neighbour in zip(labels, neighbours):
        print("nearest to {} is {}".format(label, neighbour))

    cx, cy = centroid(points)
    print("\nCentroid: ({:.3f}, {:.3f})".format(cx, cy))

    inside = points_within(points, cx, cy, 4.0)
    print("Within 4.0 of centroid:", ", ".join(label_points(inside)))

    spread = distances_from((cx, cy), points)
    print("Max distance from centroid: {:.3f}".format(max(spread)))


if __name__ == "__main__":
    main()

