def sum_digits(n):
    """Return the sum of the decimal digits of a non-negative integer."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")
    return sum([int(ch) for ch in str(n)])


def digit_counts(n):
    """Map each digit 0-9 to how many times it occurs in n."""
    text = str(n)
    pairs = [(d, text.count(str(d))) for d in range(10)]
    return {digit: count for digit, count in pairs if count}


def digital_root(n):
    """Repeatedly sum digits until a single digit remains."""
    while n > 9:
        n = sum_digits(n)
    return n


def sum_digits_chain(n):
    """Return the chain of values from n down to its digital root."""
    chain = [n]
    while chain[-1] > 9:
        chain.append(sum_digits(chain[-1]))
    return chain


def parse_numbers(text):
    """Extract the non-negative integers from a whitespace separated string."""
    tokens = text.split()
    bad = [tok for tok in tokens if not tok.isdigit()]
    if bad:
        raise ValueError("not a non-negative integer: " + ", ".join(bad))
    return [int(tok) for tok in tokens]


def format_chain(n):
    """Render the digit-sum chain of n as an arrow separated string."""
    return " -> ".join([str(value) for value in sum_digits_chain(n)])


def describe(n, width):
    """Build one report line for n, padded to the given number width."""
    counts = digit_counts(n)
    busiest = max(counts, key=lambda d: (counts[d], d))
    detail = ", ".join(["%d x%d" % (d, counts[d]) for d in sorted(counts)])
    return "%*d  sum=%3d  root=%d  [%s]  most=%d  chain: %s" % (
        width, n, sum_digits(n), digital_root(n), detail, busiest, format_chain(n)
    )


def report(numbers):
    """Build report lines describing the digit sums of each number."""
    width = max([len(str(n)) for n in numbers])
    return [describe(n, width) for n in numbers]


