    totals = [sum_digits(n) for n in numbers]
    print("grand total of digit sums:", sum(totals))
    repdigits = [n for n in numbers if len(digit_counts(n)) == 1]
    print("numbers built from a single digit:", repdigits)


if __name__ == "__main__":
