BEATS = {'rock': 'scissors', 'paper': 'rock', 'scissors': 'paper'}


def normalize(choice):
    if not isinstance(choice, str):
        raise TypeError(f"choice must be a string, got {type(choice).__name__}")
    cleaned = choice.strip().lower()
    if cleaned not in BEATS:
        options = ", ".join(sorted(BEATS))
        raise ValueError(f"invalid choice {choice!r}; expected one of: {options}")
    return cleaned


def rock_paper_scissors(player1_choice, player2_choice):
    first, second = [normalize(c) for c in (player1_choice, player2_choice)]
    if first == second:
        return "It's a tie!"
    if BEATS[first] == second:
        return 'Player 1 wins!'
    return 'Player 2 wins!'


def play_rounds(rounds):
    return [rock_paper_scissors(p1, p2) for p1, p2 in rounds]


def tally(results):
    counts = {}
    for outcome in results:
        counts[outcome] = counts.get(outcome, 0) + 1
    return counts


def score_board(results):
    wins = [outcome for outcome in results if outcome != "It's a tie!"]
    p1 = len([outcome for outcome in wins if outcome == 'Player 1 wins!'])
    return {'player1': p1, 'player2': len(wins) - p1, 'ties': len(results) - len(wins)}


def format_round(index, p1, p2, result):
    return f"Round {index}: {p1:>8} vs {p2:<8} -> {result}"


def report(rounds):
    results = play_rounds(rounds)
    lines = [
        format_round(i, p1, p2, result)
        for i, ((p1, p2), result) in enumerate(zip(rounds, results), start=1)
    ]
    board = score_board(results)
    lines.append(
        "Score: Player 1 = {player1}, Player 2 = {player2}, Ties = {ties}".format(**board)
    )
    summary = [f"{outcome} x{count}" for outcome, count in sorted(tally(results).items())]
    lines.append("Summary: " + "; ".join(summary))
    return "\n".join(lines)


def describe_rejection(value):
    try:
        normalize(value)
    except (TypeError, ValueError) as error:
        return f"{value!r}: {type(error).__name__}: {error}"
    return f"{value!r}: accepted"


def main():
    rounds = [
        ('rock', 'scissors'),
        ('paper', 'rock'),
        ('scissors', 'ROCK'),
        (' paper ', 'scissors'),
        ('rock', 'rock'),
    ]
    print(report(rounds))
    problems = [describe_rejection(value) for value in ('lizard', 'spock', 42)]
    print("\nRejected inputs:")
    for problem in problems:
        print("  " + problem)


if __name__ == '__main__':
    main()

