import math


def calculate_std_dev(numbers):
    n = len(numbers)
    mean = sum(numbers) / n
    squared_deviations = [(x - mean) ** 2 for x in numbers]
    variance = sum(squared_deviations) / (n - 1)
    return math.sqrt(variance)


def parse_dataset(line):
    return [float(token) for token in line.replace(",", " ").split()]


def validate_dataset(numbers):
    problems = []
    if len(numbers) < 2:
        problems.append("need at least two values")
    infinite = [x for x in numbers if math.isinf(x)]
    if infinite:
        problems.append("infinite values are not allowed")
    if [x for x in numbers if math.isnan(x)]:
        problems.append("NaN values are not allowed")
    return problems


def z_scores(numbers):
    mean = sum(numbers) / len(numbers)
    sd = calculate_std_dev(numbers)
    if sd == 0.0:
        return [0.0 for _ in numbers]
    return [(x - mean) / sd for x in numbers]


def outliers(numbers, threshold=2.0):
    scores = z_scores(numbers)
    return [x for x, z in zip(numbers, scores) if abs(z) > threshold]


def describe(numbers):
    mean = sum(numbers) / len(numbers)
    return {
        "count": len(numbers),
        "mean": mean,
        "std_dev": calculate_std_dev(numbers),
        "min": min(numbers),
        "max": max(numbers),
        "outliers": outliers(numbers),
    }


def format_report(label, numbers):
    stats = describe(numbers)
    lines = ["%s (n=%d)" % (label, stats["count"])]
    lines.append("  mean    : %.3f" % stats["mean"])
    lines.append("  std dev : %.3f" % stats["std_dev"])
    lines.append("  range   : %.3f .. %.3f" % (stats["min"], stats["max"]))
    if stats["outliers"]:
        marks = ["%.3f" % x for x in stats["outliers"]]
        lines.append("  outliers: " + ", ".join(marks))
    return "\n".join(lines)


def main():
    raw_inputs = [
