import math


def calculate_std_dev(numbers):
    n = len(numbers)
    mean = sum(numbers) / n
    squared_deviations = []
    for x in numbers:
        squared_deviations.append((x - mean) ** 2)
    variance = sum(squared_deviations) / (n - 1)
    return math.sqrt(variance)


def parse_dataset(line):
    result = []
    for token in line.replace(",", " ").split():
        result.append(float(token))
    return result


def validate_dataset(numbers):
    problems = []
    if len(numbers) < 2:
        problems.append("need at least two values")
    infinite = []
    for x in numbers:
        if math.isinf(x):
            infinite.append(x)
    if infinite:
        problems.append("infinite values are not allowed")
    nans = []
    for x in numbers:
        if math.isnan(x):
            nans.append(x)
    if nans:
        problems.append("NaN values are not allowed")
    return problems


def z_scores(numbers):
    mean = sum(numbers) / len(numbers)
    sd = calculate_std_dev(numbers)
    if sd == 0.0:
        zeros = []
        for _ in numbers:
            zeros.append(0.0)
        return zeros
    scores = []
    for x in numbers:
        scores.append((x - mean) / sd)
    return scores


def outliers(numbers, threshold=2.0):
    scores = z_scores(numbers)
    found = []
    for x, z in zip(numbers, scores):
        if abs(z) > threshold:
            found.append(x)
    return found


def describe(numbers):
    mean = sum(numbers) / len(numbers)
    return {
        "count": len(numbers),
        "mean": mean,
        "std_dev": calculate_std_dev(numbers),
        "min": min(numbers),
        "max": max(numbers),
        "outliers": outliers(numbers),
    }


def format_report(label, numbers):
    stats = describe(numbers)
    lines = ["%s (n=%d)" % (label, stats["count"])]
    lines.append("  mean    : %.3f" % stats["mean"])
    lines.append("  std dev : %.3f" % stats["std_dev"])
    lines.append("  range   : %.3f .. %.3f" % (stats["min"], stats["max"]))
    if stats["outliers"]:
        marks = []
        for x in stats["outliers"]:
            marks.append("%.3f" % x)
        lines.append("  outliers: " + ", ".join(marks))
    return "\n".join(lines)


def main():
    raw_inputs = [
        ("sequence", "1, 2, 3, 4, 5"),
        ("constant", "10 10 10"),
        ("with spike", "4 5 6 5 4 30"),
        ("too short", "7"),
    ]
    datasets = []
    for label, text in raw_inputs:
        datasets.append((label, parse_dataset(text)))
    for label, numbers in datasets:
        problems = validate_dataset(numbers)
        if problems:
            print("%s: skipped (%s)" % (label, "; ".join(problems)))
        else:
            print(format_report(label, numbers))


