def validate_sequence(numbers):
    """Return the numbers as a list of ints, raising ValueError on bad input."""
    if not isinstance(numbers, (list, tuple)):
        raise ValueError("numbers must be a list or tuple")
    bad = [item for item in numbers if not isinstance(item, int) or isinstance(item, bool)]
    if bad:
        raise ValueError("all entries must be plain integers: %r" % (bad,))
    values = [int(item) for item in numbers]
    if len(set(values)) != len(values):
        raise ValueError("entries must be unique")
    out_of_range = [v for v in values if v < 1 or v > len(values) + 1]
    if out_of_range:
        raise ValueError("entries must lie between 1 and N: %r" % (out_of_range,))
    return values


def find_missing_number(numbers):
    """Find the single missing value in an unsorted list of 1..N with one gap."""
    values = validate_sequence(numbers)
    n = len(values) + 1
    return n * (n + 1) // 2 - sum(values)


def describe(numbers):
    """Build a one-line report for a single puzzle instance."""
    missing = find_missing_number(numbers)
    shown = ", ".join([str(value) for value in numbers])
    return "[%s] -> %d" % (shown, missing)


def report(datasets):
    """Describe every dataset, reporting failures instead of crashing."""
    lines = []
    for dataset in datasets:
        try:
            lines.append(describe(dataset))
        except ValueError as error:
            lines.append("%r -> error: %s" % (dataset, error))
    return lines


