def join_elements(items, separator):
    if not items:
        return ""

    string_items = []
    for item in items:
        string_items.append(str(item))

    if len(string_items) == 1:
        return string_items[0]

    all_parts = []

    paired_items = []
    for i in range(len(string_items) - 1):
        paired_items.append((string_items[i], separator))

    flattened_parts = []
    for pair in paired_items:
        for part in pair:
            flattened_parts.append(part)

    all_parts.extend(flattened_parts)

    remaining_item = [string_items[-1]]

    final_parts = []
    for p in all_parts:
        if p != '':
            final_parts.append(p)

    final_parts.extend(remaining_item)

    processed_parts = []
    for part in final_parts:
        processed_parts.append(part.strip())

    filtered_parts = []
    for part in processed_parts:
        if part:
            filtered_parts.append(part)

    result = ""

    result_list = []
    for part in filtered_parts:
        result_list.append(part)

    for part in result_list:
        result += part

    return result

