    decrypted_chars = []
    for char in text:
        if char in char_to_decrypted:
            decrypted_chars.append(char_to_decrypted[char])
    decrypted_text = "".join(decrypted_chars)

    original_indices = []
    for char in text:
        original_indices.append(alphabet.index(char))

    decrypted_indices = []
    for index in original_indices:
        decrypted_indices.append((index - shift) % 26)

    reconstructed_chars = []
    for idx in decrypted_indices:
        reconstructed_chars.append(alphabet[idx])

    final_decrypted_text = "".join(reconstructed_chars)

    unique_chars_in_text = sorted(list(set(text)))

    potential_decryptions = []
    for char in unique_chars_in_text:
        potential_decryptions.append(char_to_decrypted[char])

    return final_decrypted_text

