import re
from collections import Counter

NAME_RUN = re.compile(r"[A-Za-z0-9_]+")


def _require_text(text):
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    return text


def _clean(token):
    """Drop the leading '@' and keep only the leading run of name characters."""
    match = NAME_RUN.match(token.lstrip("@"))
    return match.group(0) if match else ""


def extract_mentions(text):
    """Return the mention names (without '@') found in text, in order."""
    _require_text(text)
    candidates = [token for token in text.split() if token.startswith("@")]
    names = [_clean(token) for token in candidates]
    return [name for name in names if name]


def unique_mentions(texts):
    """Mentions across several texts, de-duplicated, first-seen order kept."""
    everything = [name for text in texts for name in extract_mentions(text)]
    seen = set()
    ordered = []
    for name in everything:
        if name.lower() not in seen:
            seen.add(name.lower())
            ordered.append(name)
    return ordered


def mention_counts(texts):
    """Count how often each mention (case-insensitive) appears."""
    lowered = [name.lower() for text in texts for name in extract_mentions(text)]
    return Counter(lowered)


def top_mentions(counts, limit):
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [name for name, _ in ranked[:limit]]


def format_report(texts):
    counts = mention_counts(texts)
    header = "%d message(s), %d distinct mention(s)" % (len(texts), len(counts))
    body = ["  %-10s %d" % (name, counts[name]) for name in top_mentions(counts, 5)]
    return "\n".join([header] + body)


def main():
    texts = [
        "Hello @user1, how are you @user2?",
        "No mentions here.",
        "@user1 ping @dev_team and (@user3) -- thanks!",
        "email me at foo@example.com or ask @USER2",
    ]
    rows = [(text, extract_mentions(text)) for text in texts]
    for text, mentions in rows:
        print("%-45s -> %s" % (text, mentions))
    print("all mentions:", ", ".join(unique_mentions(texts)))
    print(format_report(texts))


if __name__ == "__main__":
    main()

