KNOWN_LEVELS = ['DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL']


def parse_log_line(log_line):
    parts = [piece.strip() for piece in log_line.split(' - ', 2)]
    if len(parts) < 3:
        raise ValueError('malformed log line: %r' % log_line)
    timestamp, level, message = parts
    return {'timestamp': timestamp, 'level': level.upper(), 'message': message}


def parse_log_lines(lines):
    candidates = [line.strip() for line in lines]
    return [parse_log_line(line) for line in candidates if line]


def filter_by_level(entries, level):
    wanted = level.upper()
    return [entry for entry in entries if entry['level'] == wanted]


def count_by_level(entries):
    counts = {}
    for entry in entries:
        counts[entry['level']] = counts.get(entry['level'], 0) + 1
    return counts


def unknown_levels(entries):
    levels = [level for level in count_by_level(entries) if level not in KNOWN_LEVELS]
    levels.sort()
    return levels


def format_entry(entry):
    return '[{level:<8}] {timestamp} :: {message}'.format(**entry)


def build_report(entries):
    counts = count_by_level(entries)
    ordered = [level for level in KNOWN_LEVELS if level in counts]
    ordered += unknown_levels(entries)
    lines = ['Total entries: %d' % len(entries)]
    lines += ['  %-8s %d' % (level, counts[level]) for level in ordered]
    problems = filter_by_level(entries, 'ERROR') + filter_by_level(entries, 'CRITICAL')
