"""Utilities for analysing character frequencies in a string."""

from collections import Counter


def clean_text(text, ignore_spaces=False):
    """Return the characters of *text* that should take part in the counting."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    if ignore_spaces:
        return [ch for ch in text if not ch.isspace()]
    return list(text)


def unique_in_order(chars):
    """Unique characters, keeping the order of first appearance."""
    seen = set()
    ordered = []
    for ch in chars:
        if ch not in seen:
            seen.add(ch)
            ordered.append(ch)
    return ordered


def ordered_counts(text, ignore_spaces=False):
    """(character, occurrences) pairs ordered by first appearance in *text*."""
    chars = clean_text(text, ignore_spaces)
    tally = Counter(chars)
    return [(ch, tally[ch]) for ch in unique_in_order(chars)]


def least_frequent_char(text):
    """The rarest character of *text*; ties go to the first one encountered."""
    pairs = ordered_counts(text)
    if not pairs:
        raise ValueError("text must not be empty")
    lowest = min([n for _, n in pairs])
    rarest = [ch for ch, n in pairs if n == lowest]
    return rarest[0]


def most_frequent_char(text):
    """The most common character of *text*, first encountered wins ties."""
    pairs = ordered_counts(text)
    if not pairs:
        raise ValueError("text must not be empty")
    highest = max([n for _, n in pairs])
    return [ch for ch, n in pairs if n == highest][0]


def describe(ch):
    """A printable form of a character, so whitespace stays visible."""
    return repr(ch) if ch.isspace() else ch


def frequency_report(text, ignore_spaces=False):
    """A multi-line table of characters ordered from rarest to most common."""
    order = sorted(ordered_counts(text, ignore_spaces), key=lambda pair: pair[1])
    rows = ["%-4s %d" % (describe(ch), n) for ch, n in order]
    return "\n".join(rows)


def main():
    samples = ["hello world", "aabbc", "  mississippi river  "]
    summaries = [
        "%-24s rarest=%s most=%s"
        % (repr(s), describe(least_frequent_char(s)), describe(most_frequent_char(s)))
        for s in samples
    ]
    for line in summaries:
        print(line)
    print()
    print(frequency_report(samples[-1], ignore_spaces=True))


if __name__ == "__main__":
    main()

