def shape(matrix):
    """Return (rows, cols) of a rectangular matrix, or raise ValueError."""
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of rows")
    widths = [len(row) for row in matrix]
    if len(set(widths)) != 1 or widths[0] == 0:
        raise ValueError("matrix rows must all be non-empty and of equal length")
    bad = [value for row in matrix for value in row if not isinstance(value, (int, float))]
    if bad:
        raise ValueError("matrix entries must be int or float, found %r" % bad[0])
    return len(matrix), widths[0]


def subtract_rows(row1, row2):
    """Element-wise difference of two rows."""
    return [a - b for a, b in zip(row1, row2)]


def matrix_subtract(matrix1, matrix2):
    """Element-wise difference matrix1 - matrix2."""
    if shape(matrix1) != shape(matrix2):
        raise ValueError("matrices must have the same dimensions")
    return [subtract_rows(row1, row2) for row1, row2 in zip(matrix1, matrix2)]


def format_number(value):
    """Print floats without trailing zeros and ints plainly."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_row(row):
    """Render every entry of a row as text."""
    return [format_number(value) for value in row]


def column_width(cells, index):
    """Width needed to right-align one column of rendered cells."""
    lengths = [len(row[index]) for row in cells]
    return max(lengths)


def format_matrix(matrix):
    """Render a matrix as aligned text rows."""
    cells = [format_row(row) for row in matrix]
    widths = [column_width(cells, index) for index in range(len(cells[0]))]
    lines = []
    for row in cells:
        padded = [text.rjust(widths[index]) for index, text in enumerate(row)]
        lines.append("[ " + "  ".join(padded) + " ]")
    return "\n".join(lines)


def row_sums(matrix):
    """Sum of each row, useful for a quick sanity report."""
    return [sum(row) for row in matrix]


def report(matrix1, matrix2):
    """Build a human-readable report of a subtraction."""
    result = matrix_subtract(matrix1, matrix2)
    blocks = [format_matrix(m) for m in (matrix1, matrix2, result)]
    labels = ["matrix1", "matrix2", "difference"]
    sections = ["%s:\n%s" % (label, block) for label, block in zip(labels, blocks)]
    sums = [format_number(total) for total in row_sums(result)]
    sections.append("row sums: " + ", ".join(sums))
    return "\n".join(sections)


def describe_failure(matrix1, matrix2):
    """Return the error message produced by an invalid subtraction."""
    try:
        matrix_subtract(matrix1, matrix2)
    except ValueError as exc:
        return str(exc)
    return "no error"


