import re
from itertools import groupby

TOKEN_PATTERN = re.compile(r"(\d+)(\D)")


def tokenize(encoded_string):
    """Split 'count_char' pairs into a list of (count, character) tuples."""
    if not isinstance(encoded_string, str):
        raise TypeError("encoded_string must be a str")
    matches = TOKEN_PATTERN.findall(encoded_string)
    consumed = sum([len(digits) + len(char) for digits, char in matches])
    if consumed != len(encoded_string):
        raise ValueError("malformed run-length encoding: %r" % encoded_string)
    tokens = [(int(digits), char) for digits, char in matches]
    zeros = [char for count, char in tokens if count == 0]
    if zeros:
        raise ValueError("zero-length run for character(s): %s" % ", ".join(zeros))
    return tokens


def run_length_decode(encoded_string):
    """Expand a run-length encoded string such as '3A2B1C' into 'AAABBC'."""
    tokens = tokenize(encoded_string)
    return "".join([char * count for count, char in tokens])


def run_length_encode(decoded_string):
    """Inverse of run_length_decode, used to confirm a lossless round trip."""
    return "".join(["%d%s" % (len(list(group)), char)
                    for char, group in groupby(decoded_string)])


def decoded_length(encoded_string):
    """Length of the decoded text without materialising it."""
    return sum([count for count, _ in tokenize(encoded_string)])


def segment_report(encoded_string):
    """Human readable description of every run in the encoded string."""
    tokens = tokenize(encoded_string)
    return [f"run {index}: {char!r} repeated {count} time(s)"
            for index, (count, char) in enumerate(tokens, start=1)]


def main():
    samples = ["3A2B1C", "1X", "10Z3 2!", "12a"]
    decoded = [(sample, run_length_decode(sample)) for sample in samples]
    for encoded, text in decoded:
        print(f"{encoded} -> {text!r} (length {decoded_length(encoded)})")

    for line in segment_report(samples[2]):
        print("  " + line)

    mismatches = [encoded for encoded, text in decoded
                  if run_length_encode(text) != encoded]
    print("round trip mismatches:", mismatches or "none")

    broken = ["A3", "3", "", "3A0B"]
    problems = []
    for candidate in broken:
        try:
            run_length_decode(candidate)
        except ValueError as exc:
            problems.append((candidate, str(exc)))
    for candidate, message in problems:
        print(f"rejected {candidate!r}: {message}")


if __name__ == "__main__":
    main()

