def decimal_to_hex(decimal_num):
    if not isinstance(decimal_num, int) or isinstance(decimal_num, bool):
        raise TypeError("decimal_num must be an int")
    if decimal_num == 0:
        return "0"
    magnitude = abs(decimal_num)
    reversed_digits = []
    while magnitude:
        reversed_digits.append(DIGITS[magnitude % 16])
        magnitude //= 16
    hex_string = "".join(reversed_digits[::-1])
    return "-" + hex_string if decimal_num < 0 else hex_string


def hex_to_decimal(hex_string):
    body = hex_string[1:] if hex_string.startswith("-") else hex_string
    place_values = [DIGITS.index(ch) * 16 ** power
                    for power, ch in enumerate(reversed(body.upper()))]
    value = sum(place_values)
    return -value if hex_string.startswith("-") else value


