PAIRS = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)
DIGIT_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def int_to_roman(num):
    """Convert an integer between 1 and 3999 into its Roman numeral string."""
    if not isinstance(num, int) or isinstance(num, bool):
        raise TypeError("num must be an integer")
    if not 1 <= num <= 3999:
        raise ValueError("num must be between 1 and 3999")
    remaining = num
    parts = []
    for value, symbol in PAIRS:
        count, remaining = divmod(remaining, value)
        parts.append(symbol * count)
    return "".join(parts)


def roman_to_int(roman):
    """Convert a Roman numeral string back into an integer."""
    digits = [DIGIT_VALUES[char] for char in roman.upper()]
    total = 0
    for i, value in enumerate(digits):
        following = digits[i + 1:]
        if following and max(following) > value:
            total -= value
        else:
            total += value
    return total


def convert_range(start, end):
    """Return the Roman numerals for every integer from start to end inclusive."""
    return [int_to_roman(n) for n in range(start, end + 1)]


def longest_numerals(limit):
    """Find the integers up to limit whose numerals are the longest."""
    lengths = [len(int_to_roman(n)) for n in range(1, limit + 1)]
    widest = max(lengths)
    return [n for n, size in enumerate(lengths, start=1) if size == widest]


def format_table(numbers):
    """Build an aligned two-column report of numbers and their numerals."""
    numerals = [int_to_roman(n) for n in numbers]
    width = max(len(text) for text in numerals)
    rows = [f"{n:>4}  {text:<{width}}" for n, text in zip(numbers, numerals)]
    return "\n".join(rows)


def main():
    print(format_table([3, 58, 1994, 2024, 3999]))
    roundtrip = [roman_to_int(text) for text in convert_range(1, 500)]
    print("roundtrip ok:", roundtrip == list(range(1, 501)))
    winners = longest_numerals(1000)
    print("longest numerals below 1000:", ", ".join(int_to_roman(n) for n in winners))
    for label in [f"{year} -> {int_to_roman(year)}" for year in (1066, 1492, 1776)]:
        print(label)


if __name__ == "__main__":
    main()

