def to_minutes(clock):
    fields = clock.split(":")
    if len(fields) != 2:
        raise ValueError(f"bad clock time: {clock!r}")
    numbers = [int(field) for field in fields]
    hours, minutes = numbers
    if not (0 <= hours < 24 and 0 <= minutes < 60):
        raise ValueError(f"clock time out of range: {clock!r}")
    return hours * 60 + minutes


def format_minutes(total):
    return "{:02d}:{:02d}".format(total // 60, total % 60)


def parse_interval(text):
    parts = text.split("-")
    if len(parts) != 2:
        raise ValueError(f"bad interval: {text!r}")
    bounds = [to_minutes(part.strip()) for part in parts]
    start, end = bounds
    if start >= end:
        raise ValueError(f"interval does not advance in time: {text!r}")
    return (start, end)


def check_meeting(meeting):
    if len(meeting) != 2:
        raise ValueError(f"a meeting needs exactly two times: {meeting!r}")
    non_ints = [value for value in meeting if not isinstance(value, int)]
    if non_ints:
        raise TypeError(f"times must be integers: {non_ints!r}")
    if meeting[0] > meeting[1]:
