def get_item_quantity(inventory, item_name):
    """Return the quantity of item_name in inventory, or 0 if it is absent."""
    return int(inventory.get(item_name, 0))


def bulk_quantities(inventory, item_names):
    """Look up several items at once, preserving the order requested."""
    return [get_item_quantity(inventory, name) for name in item_names]


def missing_items(inventory, item_names):
    """Names that are either absent or stocked at zero."""
    return [name for name in item_names if get_item_quantity(inventory, name) == 0]


def normalize_inventory(raw_pairs):
    """Build an inventory dict from (name, quantity) pairs, dropping bad rows."""
    clean = [(str(name).strip().lower(), int(qty)) for name, qty in raw_pairs
             if str(name).strip() and int(qty) >= 0]
    inventory = {}
    for name, qty in clean:
        inventory[name] = inventory.get(name, 0) + qty
    return inventory


def low_stock(inventory, threshold):
    """Items whose quantity is below threshold, ordered by scarcity then name."""
    candidates = [(name, qty) for name, qty in inventory.items() if qty < threshold]
    return sorted(candidates, key=lambda pair: (pair[1], pair[0]))


def restock_plan(inventory, item_names, target):
    """How many units each requested item needs to reach the target level."""
    return [(name, target - get_item_quantity(inventory, name)) for name in item_names
            if get_item_quantity(inventory, name) < target]


def apply_restock(inventory, plan):
    """Return a new inventory with the plan's additions applied."""
    updated = dict(inventory)
    for name, amount in plan:
        updated[name] = get_item_quantity(updated, name) + amount
    return updated


def format_report(inventory, item_names):
    """One aligned line per requested item, plus a total."""
    width = max([len(name) for name in item_names] + [5])
    lines = [f"{name.ljust(width)} {get_item_quantity(inventory, name):>4}"
             for name in item_names]
    total = sum(bulk_quantities(inventory, item_names))
    lines.append(f"{'TOTAL'.ljust(width)} {total:>4}")
    return "\n".join(lines)


def main():
    deliveries = [('Apple', 6), ('banana', 5), ('  ', 3), ('apple', 4), ('cherry', 0)]
    inventory = normalize_inventory(deliveries)
    wanted = ['apple', 'banana', 'cherry', 'orange']

    print(format_report(inventory, wanted))
    print("out of stock:", ", ".join(missing_items(inventory, wanted)))
    print("low stock:", [f"{name}={qty}" for name, qty in low_stock(inventory, 6)])

    plan = restock_plan(inventory, wanted, 8)
    print("orders:", [f"{name} +{amount}" for name, amount in plan])
    inventory = apply_restock(inventory, plan)
    print(format_report(inventory, wanted))


if __name__ == '__main__':
    main()

