def calculate_simple_interest(principal, rate, time):
    """Return the simple interest earned on `principal` at `rate`% for `time` years."""
    _validate(principal, rate, time)
    return principal * rate * time / 100.0


def _validate(principal, rate, time):
    values = [principal, rate, time]
    bad = [v for v in values if not isinstance(v, (int, float)) or isinstance(v, bool)]
    if bad:
        raise TypeError("principal, rate and time must be numeric: %r" % (bad,))
    negatives = [v for v in values if v < 0]
    if negatives:
        raise ValueError("values must be non-negative: %r" % (negatives,))
    if time != int(time):
        raise ValueError("time must be a whole number of years: %r" % (time,))


def interest_schedule(principal, rate, time):
    """Return the cumulative interest at the end of each year, year 1 .. time."""
    _validate(principal, rate, time)
    years = range(1, int(time) + 1)
    return [calculate_simple_interest(principal, rate, year) for year in years]


def total_amounts(principal, rate, time):
    """Return the balance (principal + interest) at the end of each year."""
    return [principal + earned for earned in interest_schedule(principal, rate, time)]


def parse_case(line):
    """Parse a 'principal,rate,time' line into numeric arguments."""
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 3:
        raise ValueError("expected 3 comma-separated fields, got %d" % len(fields))
    numbers = [float(field) for field in fields]
    return numbers[0], numbers[1], int(numbers[2])


def format_schedule(principal, rate, time):
    rows = zip(interest_schedule(principal, rate, time),
               total_amounts(principal, rate, time))
    lines = ["  year %2d: interest %10.2f   balance %10.2f" % (index, earned, balance)
             for index, (earned, balance) in enumerate(rows, start=1)]
    return "\n".join(lines)


def report(lines):
    """Build a text report for a sequence of 'principal,rate,time' input lines."""
    cases = [parse_case(line) for line in lines if line.strip()]
    chunks = []
    for principal, rate, time in cases:
        interest = calculate_simple_interest(principal, rate, time)
