from collections import Counter


def normalize(text):
    """Return the significant characters of *text* in lower case."""
    return [char.lower() for char in text if not char.isspace()]


def are_anagrams(str1, str2):
    """Return True when str1 and str2 are anagrams (case and spaces ignored)."""
    letters1 = normalize(str1)
    letters2 = normalize(str2)
    if len(letters1) != len(letters2):
        return False
    return Counter(letters1) == Counter(letters2)


def signature(word):
    """Return a canonical key shared by every anagram of *word*."""
    return "".join(sorted(normalize(word)))


def group_anagrams(words):
    """Group the given words into buckets of mutual anagrams."""
    buckets = {}
    for word in words:
        buckets.setdefault(signature(word), []).append(word)
    keys = sorted(buckets, key=lambda key: (-len(buckets[key]), key))
    return [buckets[key] for key in keys]


def find_anagrams(word, candidates):
    """Return the candidates that are anagrams of *word*, excluding copies of it."""
    return [other for other in candidates if are_anagrams(word, other) and other != word]


def letter_differences(str1, str2):
    """Return the letters that prevent the two strings from being anagrams."""
    counts = Counter(normalize(str1))
    counts.subtract(Counter(normalize(str2)))
    unbalanced = [letter for letter, amount in counts.items() if amount != 0]
    return sorted(unbalanced)


def describe_pair(str1, str2):
    """Build a human readable verdict for a single pair of strings."""
    if are_anagrams(str1, str2):
        return "{!r} and {!r} are anagrams".format(str1, str2)
    missing = letter_differences(str1, str2)
    if not missing:
        return "{!r} and {!r} differ in length only".format(str1, str2)
    return "{!r} and {!r} differ in: {}".format(str1, str2, ", ".join(missing))


def main():
    pairs = [
        ("listen", "silent"),
        ("hello", "world"),
        ("Dormitory", "Dirty Room"),
        ("night", "thing!"),
    ]
    for line in [describe_pair(first, second) for first, second in pairs]:
        print(line)

    words = ["stop", "pots", "tops", "opt", "top", "spot", "banana"]
    print("\nAnagram families:")
    for family in group_anagrams(words):
        print("  " + " / ".join(family))

    target = "top"
    print("\nRearrangements of {!r}: {}".format(target, find_anagrams(target, words)))
    counts = [len(normalize(word)) for word in words]
    print("Total letters inspected:", sum(counts))


if __name__ == "__main__":
