def euclidean_distance_2d(x1: float, y1: float, x2: float, y2: float) -> float:
    coords = [float(v) for v in (x1, y1, x2, y2)]
    deltas = [b - a for a, b in ((coords[0], coords[2]), (coords[1], coords[3]))]
    return math.sqrt(sum(d * d for d in deltas))


def parse_point(text: str) -> tuple:
    parts = [chunk.strip() for chunk in text.replace("(", "").replace(")", "").split(",")]
    if len(parts) != 2:
        raise ValueError(f"expected two coordinates, got {len(parts)}: {text!r}")
    numbers = [float(p) for p in parts]
    return numbers[0], numbers[1]


def parse_pairs(lines) -> list:
    pairs = []
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        halves = [half for half in stripped.split(";") if half.strip()]
        if len(halves) != 2:
            raise ValueError(f"expected two points separated by ';': {stripped!r}")
        pairs.append(tuple(parse_point(h) for h in halves))
    return pairs


