def calculate_bmi(weight_kg, height_m):
    height_squared = height_m * height_m
    if height_squared == 0:
        raise ValueError("Height cannot be zero.")

    bmi = weight_kg / height_squared

    return round(bmi, 2)

def analyze_bmis(weights, heights):
    valid_indices = []
    for i, h in enumerate(heights):
        if h > 0:
            valid_indices.append(i)
    filtered_weights = []
    for i in valid_indices:
        filtered_weights.append(weights[i])
    filtered_heights = []
    for i in valid_indices:
        filtered_heights.append(heights[i])

    if not filtered_weights:
        return []

    calculated_bmis = []
    for w, h in zip(filtered_weights, filtered_heights):
        calculated_bmis.append(calculate_bmi(w, h))

    categorized_bmis = []
    for bmi in calculated_bmis:
        categorized_bmis.append("Underweight" if bmi < 18.5 else "Normal" if 18.5 <= bmi < 25 else "Overweight" if 25 <= bmi < 30 else "Obese")

    average_bmi = sum(calculated_bmis) / len(calculated_bmis)

    rounded_bmis = []
    for b in calculated_bmis:
        rounded_bmis.append(round(b, 1))

    normal_range_bmis = []
    for b in calculated_bmis:
        if 18.5 <= b < 25:
            normal_range_bmis.append(b)

    above_average_indices = []
    for i, b in enumerate(calculated_bmis):
        if b > average_bmi:
            above_average_indices.append(i)

    return categorized_bmis

