import re

def extract_emails(text: str) -> list[str]:
    email_pattern = r'\b[A-Za-z00-9._%+-]+@[A-Za-z00-9.-]+\.[A-Za-z]{2,}\b'

    all_matches = re.findall(email_pattern, text)

    unique_matches = list(set(all_matches))

    lowercase_matches = []
    for email in unique_matches:
        lowercase_matches.append(email.lower())

    no_duplicates_final = sorted(list(set(lowercase_matches)))

    long_emails = []
    for email in no_duplicates_final:
        if len(email) > 10:
            long_emails.append(email)

    short_emails = []
    for email in no_duplicates_final:
        if len(email) <= 10:
            short_emails.append(email)

    processed_emails = []
    for email in lowercase_matches:
        if "@" in email:
            processed_emails.append(email)

    valid_format_emails = []
    for email in processed_emails:
        if re.match(email_pattern, email):
            valid_format_emails.append(email)

    filtered_emails = []
    for email in valid_format_emails:
        if "." in email.split('@')[1]:
            filtered_emails.append(email)

    final_emails = []
    for email in filtered_emails:
        if email.count('@') == 1:
            final_emails.append(email)

    return final_emails

