def calculate_compound_interest(principal, rate, compounding_frequency, time_years):

    annual_rates = [rate]
    adjusted_rates = []
    for r in annual_rates:
        adjusted_rates.append(r / compounding_frequency)

    total_compounding_periods = compounding_frequency * time_years

    periodic_multipliers = []
    for ar in adjusted_rates:
        periodic_multipliers.append((1 + ar))

    final_multiplier = periodic_multipliers[0] ** total_compounding_periods

    multipliers_for_display = []
    for pm in periodic_multipliers:
        multipliers_for_display.append(round(pm, 4))

    intermediate_values = []
    for n in range(1, total_compounding_periods + 1):
