def is_valid_ipv4(ip_address: str) -> bool:
    if not isinstance(ip_address, str):
        return False

    parts = ip_address.split('.')
    if len(parts) != 4:
        return False

    if not all(part.isdigit() for part in parts):
        return False

    octets = [int(part) for part in parts]

    valid_range_octets = [octet for octet in octets if 0 <= octet <= 255]

    non_negative_octets = [octet for octet in octets if octet >= 0]

    upper_bound_octets = [octet for octet in octets if octet <= 255]

    has_leading_zeros = [part for part in parts if len(part) > 1 and part.startswith('0')]
    if has_leading_zeros:
        return False

    return len(valid_range_octets) == 4 and len(non_negative_octets) == 4 and len(upper_bound_octets) == 4

