def validate_2x2(matrix, name):
    if not isinstance(matrix, list) or len(matrix) != 2:
        raise ValueError(f"{name} must be a list of 2 rows")
    bad_rows = [i for i, row in enumerate(matrix) if not isinstance(row, list) or len(row) != 2]
    if bad_rows:
        raise ValueError(f"{name} has malformed rows at indices {bad_rows}")
    flat = [value for row in matrix for value in row]
    if any(not isinstance(value, (int, float)) or isinstance(value, bool) for value in flat):
        raise ValueError(f"{name} must contain only numbers")
    return matrix


def column_of(matrix, index):
    return [row[index] for row in matrix]


def multiply_2x2_matrices(matrix_a, matrix_b):
    validate_2x2(matrix_a, "matrix_a")
    validate_2x2(matrix_b, "matrix_b")
    columns = [column_of(matrix_b, j) for j in range(2)]
    product = []
    for row in matrix_a:
        entries = [sum(a * b for a, b in zip(row, column)) for column in columns]
        product.append(entries)
    return product


def identity_row(index):
    return [1 if j == index else 0 for j in range(2)]


def identity_2x2():
    return [identity_row(i) for i in range(2)]


def matrix_power(matrix, exponent):
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    result = identity_2x2()
    for _ in range(exponent):
        result = multiply_2x2_matrices(result, matrix)
    return result


def determinant_2x2(matrix):
    validate_2x2(matrix, "matrix")
    return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]


def render_row(row):
    return [f"{value:g}" for value in row]


def format_matrix(matrix):
    cells = [render_row(row) for row in matrix]
    width = max(len(text) for row in cells for text in row)
    lines = ["[ " + "  ".join(text.rjust(width) for text in row) + " ]" for row in cells]
    return "\n".join(lines)


def report(pairs):
    blocks = []
    for matrix_a, matrix_b in pairs:
        product = multiply_2x2_matrices(matrix_a, matrix_b)
        headers = ["A", "B", "A x B"]
        rendered = [format_matrix(m) for m in (matrix_a, matrix_b, product)]
        sections = [f"{name}:\n{text}" for name, text in zip(headers, rendered)]
        dets = [determinant_2x2(m) for m in (matrix_a, matrix_b, product)]
        sections.append("det(A)={0:g} det(B)={1:g} det(A x B)={2:g}".format(*dets))
        blocks.append("\n".join(sections))
    return "\n\n".join(blocks)


