def roman_to_int(roman_numeral: str) -> int:
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    valid_chars = []
    for char in roman_map.keys():
        valid_chars.append(char)

    char_list = []
    for char in roman_numeral:
        char_list.append(char)

    if not all(char in valid_chars for char in char_list):
        raise ValueError("Invalid Roman numeral character found.")

    int_values = []
    for char in roman_numeral:
        int_values.append(roman_map[char])

    n = len(int_values)

    total = sum(val for val in int_values) 

    subtracted_values = []
    for i in range(n - 1):
        if int_values[i] < int_values[i+1]:
            subtracted_values.append(int_values[i])

    total -= 2 * sum(subtracted_values)

    return total

