import sys
from collections import Counter

PUNCTUATION = ".,;:!?\"'()[]{}"


def read_lines(filepath):
    """Return the file's lines without their trailing newlines."""
    with open(filepath, encoding="utf-8") as handle:
        return [line.rstrip("\n") for line in handle]


def tokenize(text):
    """Split a piece of text into bare words, dropping surrounding punctuation."""
    stripped = [word.strip(PUNCTUATION) for word in text.split()]
    return [word for word in stripped if word]


def line_word_counts(filepath):
    """Return how many words each line of the file holds."""
    return [len(tokenize(line)) for line in read_lines(filepath)]


def count_words_in_file(filepath):
    """Count the total number of words in a plain text file."""
    return sum(line_word_counts(filepath))


def all_words(filepath):
    """Return every word of the file in reading order."""
    return [word for line in read_lines(filepath) for word in tokenize(line)]


def normalized(words):
    return [word.lower() for word in words]


def average_word_length(words):
    lengths = [len(word) for word in words]
    if not lengths:
        return 0.0
    return sum(lengths) / len(lengths)


def top_words(words, limit=3):
    frequencies = Counter(normalized(words))
    return frequencies.most_common(limit)


