import math


def _validate_point(p):
    if len(p) != 3:
        raise ValueError(f"expected 3 coordinates, got {len(p)}: {p!r}")
    coords = [float(c) for c in p]
    return tuple(coords)


def distance_3d(p1, p2):
    a = _validate_point(p1)
    b = _validate_point(p2)
    squares = [(u - v) ** 2 for u, v in zip(a, b)]
    return math.sqrt(sum(squares))


def path_length(points):
    legs = [distance_3d(points[i], points[i + 1]) for i in range(len(points) - 1)]
    return sum(legs)


def centroid(points):
    if not points:
        raise ValueError("centroid of an empty point set is undefined")
    cleaned = [_validate_point(p) for p in points]
    axes = [sum(c[axis] for c in cleaned) / len(cleaned) for axis in range(3)]
    return tuple(axes)


def distances_from(origin, points):
    return [distance_3d(origin, q) for q in points]


def distance_matrix(points):
    return [distances_from(p, points) for p in points]


def nearest_pair(points):
    if len(points) < 2:
        raise ValueError("need at least two points to find a nearest pair")
    pairs = [(i, j) for i in range(len(points)) for j in range(i + 1, len(points))]
    best = min(pairs, key=lambda ij: distance_3d(points[ij[0]], points[ij[1]]))
    return points[best[0]], points[best[1]], distance_3d(points[best[0]], points[best[1]])


def farthest_from_centre(points):
    centre = centroid(points)
    radii = [(distance_3d(p, centre), p) for p in points]
    return max(radii)


def format_point(p):
    parts = [f"{c:g}" for c in _validate_point(p)]
    return "(" + ", ".join(parts) + ")"


def format_matrix(points):
    matrix = distance_matrix(points)
    header = "        " + " ".join(f"{i:>7d}" for i in range(len(points)))
    body = [f"{i:>7d} " + " ".join(f"{d:7.3f}" for d in row) for i, row in enumerate(matrix)]
    return "\n".join([header] + body)


def main():
    route = [(0, 0, 0), (1, 1, 1), (1, 2, 3), (1, 2, 4), (-2, 5, 0)]
    labels = [f"P{i}={format_point(p)}" for i, p in enumerate(route)]
    print("Points:", ", ".join(labels))
    print(f"distance_3d((0,0,0), (1,1,1)) = {distance_3d((0, 0, 0), (1, 1, 1))}")
    print(f"distance_3d((1,2,3), (1,2,4)) = {distance_3d((1, 2, 3), (1, 2, 4))}")

    hops = [f"{format_point(a)}->{format_point(b)}: {distance_3d(a, b):.4f}"
            for a, b in zip(route, route[1:])]
    for line in hops:
        print("  leg", line)
    print(f"Total path length: {path_length(route):.4f}")

    print("Centroid:", format_point(centroid(route)))
    a, b, d = nearest_pair(route)
    print(f"Nearest pair: {format_point(a)} and {format_point(b)} at {d:.4f}")
    radius, outlier = farthest_from_centre(route)
    print(f"Farthest from centroid: {format_point(outlier)} at {radius:.4f}")
    print("Distance matrix:")
    print(format_matrix(route))


if __name__ == "__main__":
    main()

