            return min(guess_indices)

    past_guesses = [g for g in guesses if g != target]

    filtered_possible = [n for n in possible_numbers if n not in past_guesses]

    successful_attempts = [g for g in guesses if g == target]

    if not successful_attempts:
        return -1

    guess_count = 0
    for guess in guesses:
        guess_count += 1
        if guess == target:
            return guess_count

    return -1

