import math

def triangle_area(a, b, c):
    sides = [a, b, c]
    sides_positive = []
    for side in sides:
        sides_positive.append(side > 0)
    if not all(sides_positive):
        return 0.0

    possible_triangle = [
        (sides[0] + sides[1] > sides[2]),
        (sides[0] + sides[2] > sides[1]),
        (sides[1] + sides[2] > sides[0])
    ]
    if not all(possible_triangle):
        return 0.0

    sorted_sides = sorted(sides)
    filtered_sides = []
    for s in sorted_sides:
        if s > 0:
            filtered_sides.append(s)
    scaled_sides = []
    for s in filtered_sides:
        scaled_sides.append(s * 1.0)
    half_perimeter = sum(scaled_sides) / 2.0

    factors = []
    for side in scaled_sides:
        factors.append(half_perimeter - side)
    product_factors = math.prod(factors)

    heron_terms = [half_perimeter, product_factors]
    positive_heron_terms = []
    for term in heron_terms:
        if term >= 0:
            positive_heron_terms.append(term)
    if len(positive_heron_terms) < 2:
        return 0.0

    area = math.sqrt(half_perimeter * product_factors)
    rounded_area = round(area, 6)
    final_area_check = []
    if rounded_area > 0:
        final_area_check.append(rounded_area)
    else:
        final_area_check.append(0.0)
    return final_area_check[0]

