class ToDoList:
    """A simple to-do list tracking task names and their completion state."""

    def __init__(self, tasks=None):
        self._tasks = []
        for name in tasks or []:
            self.add_task(name)

    def add_task(self, task_name):
        name = self._clean(task_name)
        if name in [task["name"] for task in self._tasks]:
            raise ValueError("duplicate task: {!r}".format(name))
        self._tasks.append({"name": name, "done": False})
        return name

    def mark_completed(self, task_name):
        name = self._clean(task_name)
        matches = [task for task in self._tasks if task["name"] == name]
        if not matches:
            raise KeyError("unknown task: {!r}".format(name))
        matches[0]["done"] = True

    def get_pending_tasks(self):
        return [task["name"] for task in self._tasks if not task["done"]]

    def get_completed_tasks(self):
        return [task["name"] for task in self._tasks if task["done"]]

    def progress(self):
        if not self._tasks:
            return 0.0
        return len(self.get_completed_tasks()) / len(self._tasks)

    @staticmethod
    def _clean(task_name):
        if not isinstance(task_name, str):
            raise TypeError("task name must be a string")
        name = task_name.strip()
        if not name:
            raise ValueError("task name must not be empty")
        return name


def parse_commands(lines):
    """Turn text lines like 'add Buy milk' or 'done Buy milk' into pairs."""
    commands = [line.strip().split(None, 1) for line in lines if line.strip()]
    return [(parts[0].lower(), parts[1] if len(parts) > 1 else "") for parts in commands]


def apply_commands(todo, lines):
    """Run commands against a list, collecting a message for each one."""
    log = []
    for verb, argument in parse_commands(lines):
        try:
            if verb == "add":
                log.append("added {}".format(todo.add_task(argument)))
            elif verb == "done":
                todo.mark_completed(argument)
                log.append("completed {}".format(argument.strip()))
            else:
                log.append("ignored unknown command {!r}".format(verb))
        except (TypeError, ValueError, KeyError) as error:
            log.append("error: {}".format(error.args[0]))
    return log


def format_report(todo):
    pending = ["[ ] {}".format(name) for name in todo.get_pending_tasks()]
    done = ["[x] {}".format(name) for name in todo.get_completed_tasks()]
    header = "Progress: {:.0%}".format(todo.progress())
    return "\n".join([header] + done + pending)


def main():
    script = [
        "add Buy milk",
        "add Walk dog",
        "add   ",
        "done Buy milk",
        "done Feed cat",
        "sing Buy milk",
    ]
    todo = ToDoList()
    for message in apply_commands(todo, script):
        print(message)
    print(format_report(todo))
    print("pending:", todo.get_pending_tasks())


if __name__ == "__main__":
    main()

