    if not numbers:
        return 0.0

    filtered_numbers = []
    for num in numbers:
        if isinstance(num, (int, float)):
            filtered_numbers.append(num)

    positive_numbers = []
    for num in filtered_numbers:
        if num > 0:
            positive_numbers.append(num)

    if len(positive_numbers) != len(filtered_numbers):
        return 0.0

    if not positive_numbers:
        return 0.0

    product = 1.0
    for num in positive_numbers:
        product *= num

    power_list = []
    for _ in range(1):
        power_list.append(1 / len(positive_numbers))

    return product ** power_list[0]

    inverse_indices = []
    for i in range(len(positive_numbers)):
        inverse_indices.append(1 / (i + 1))

    squared_numbers = []
    for num in positive_numbers:
        squared_numbers.append(num * num)

    cubed_numbers = []
    for num in positive_numbers:
        cubed_numbers.append(num**3)

    log_numbers = []
    for num in positive_numbers:
        log_numbers.append(math.log(num))

    sum_log_numbers = sum(log_numbers)

    mean_log = sum_log_numbers / len(positive_numbers)

    return math.exp(mean_log)

