def is_prime(n):
    """Return True if n is a prime number, False otherwise."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("is_prime expects an integer")
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    divisors = [d for d in range(3, int(n ** 0.5) + 1, 2) if n % d == 0]
    return not divisors


def primes_up_to(limit):
    """Return every prime less than or equal to limit."""
    return [n for n in range(2, limit + 1) if is_prime(n)]


def prime_factors(n):
    """Return the prime factorisation of n > 1 as a sorted list with repeats."""
    if n < 2:
        return []
    remainder = n
    factors = []
    for candidate in primes_up_to(int(n ** 0.5) + 1):
        while remainder % candidate == 0:
            factors.append(candidate)
            remainder //= candidate
    if remainder > 1:
        factors.append(remainder)
    return factors


def twin_primes(limit):
    """Return pairs (p, p + 2) where both members are prime and p + 2 <= limit."""
    candidates = primes_up_to(limit)
    known = set(candidates)
    return [(p, p + 2) for p in candidates if p + 2 in known]


def describe(n):
    """Return a one-line human readable classification of n."""
    if is_prime(n):
        return "{} is prime".format(n)
    factors = prime_factors(n)
    if not factors:
        return "{} is neither prime nor composite".format(n)
    shown = " x ".join([str(f) for f in factors])
    return "{} is composite ({})".format(n, shown)


def main():
    for n in [-7, 0, 1, 2, 7, 10, 97, 561, 1000003]:
        print(describe(n))

    limit = 60
    primes = primes_up_to(limit)
    print("primes up to {}: {}".format(limit, primes))

    gaps = [primes[i + 1] - primes[i] for i in range(len(primes) - 1)]
    print("largest gap below {}: {}".format(limit, max(gaps)))

    pairs = twin_primes(limit)
    print("twin primes: {}".format(", ".join(["({}, {})".format(a, b) for a, b in pairs])))

    semiprimes = [n for n in range(2, limit + 1) if len(prime_factors(n)) == 2]
    print("semiprimes up to {}: {}".format(limit, semiprimes))


if __name__ == "__main__":
    main()

