import string

ALPHABET = string.ascii_lowercase


def letters_in(text):
    """Return the alphabetic characters of text, lowercased, in order."""
    return [ch for ch in text.lower() if ch in ALPHABET]


def missing_letters(text):
    """Return the alphabet letters absent from text, in alphabetical order."""
    present = letters_in(text)
    return [letter for letter in ALPHABET if letter not in present]


def is_pangram(text):
    """Return True if text contains every letter of the English alphabet."""
    return not missing_letters(text)


def counts_of(text):
    """Occurrences of each alphabet letter in text, aligned with ALPHABET."""
    lowered = text.lower()
    return [lowered.count(letter) for letter in ALPHABET]


def pangram_ratio(text):
    """Fraction of the alphabet covered by text, between 0.0 and 1.0."""
    present = letters_in(text)
    used = [letter for letter in ALPHABET if letter in present]
    return len(used) / len(ALPHABET)


def perfect_pangram(text):
    """True when text uses each letter exactly once."""
    off_target = [count for count in counts_of(text) if count != 1]
    return not off_target


def describe(text):
    """Build a one-line human readable verdict for a candidate sentence."""
    if is_pangram(text):
        kind = "perfect pangram" if perfect_pangram(text) else "pangram"
        return "{!r}: {}".format(text, kind)
    absent = missing_letters(text)
    shown = ", ".join(absent[:6]) + ("..." if len(absent) > 6 else "")
    return "{!r}: not a pangram ({:.0%} covered, missing {})".format(
        text, pangram_ratio(text), shown
    )


def report(sentences):
    """Return report lines, best coverage first."""
    ranked = sorted(sentences, key=pangram_ratio, reverse=True)
    return [describe(sentence) for sentence in ranked]


def main():
    sentences = [
        "The quick brown fox jumps over the lazy dog.",
        "Hello World",
        "Mr Jock, TV quiz PhD, bags few lynx",
        "Pack my box with five dozen liquor jugs!",
        "Sphinx of black quartz, judge my vow",
    ]
    for line in report(sentences):
        print(line)

    pangrams = [s for s in sentences if is_pangram(s)]
    print("{} of {} sentences are pangrams".format(len(pangrams), len(sentences)))

    totals = counts_of(" ".join(sentences))
    rare = [letter for letter, total in zip(ALPHABET, totals) if total < 4]
    print("Rarest letters across the corpus: " + " ".join(rare))


if __name__ == "__main__":
    main()

