def validate_binary(bits):
    """Return the binary string stripped of whitespace, or raise ValueError."""
    cleaned = "".join([ch for ch in bits if not ch.isspace()])
    if not cleaned:
        raise ValueError("empty binary string")
    bad = [ch for ch in cleaned if ch not in "01"]
    if bad:
        raise ValueError("invalid binary digits: " + ", ".join(bad))
    return cleaned


def binary_to_gray(bits):
    """Convert a binary string to the equivalent Gray code string."""
    cleaned = validate_binary(bits)
    pairs = zip(cleaned, cleaned[1:])
    tail = [str(int(left) ^ int(right)) for left, right in pairs]
    return cleaned[0] + "".join(tail)


def gray_to_binary(code):
    """Convert a Gray code string back to the plain binary string."""
    cleaned = validate_binary(code)
    out = [cleaned[0]]
    for digit in cleaned[1:]:
        out.append(str(int(out[-1]) ^ int(digit)))
    return "".join(out)


def gray_sequence(width):
    """Gray codes of every value representable in `width` bits, in order."""
    if width < 1:
        raise ValueError("width must be positive")
    binaries = [format(value, "0{}b".format(width)) for value in range(2 ** width)]
    return [binary_to_gray(binary) for binary in binaries]


def differing_positions(left, right):
    """Indices at which two equal-length code words differ."""
    if len(left) != len(right):
        raise ValueError("code words must have equal length")
    return [index for index, pair in enumerate(zip(left, right)) if pair[0] != pair[1]]


def format_table(width):
    """Render a value / binary / Gray table for all `width`-bit values."""
    codes = gray_sequence(width)
    rows = ["value  binary  gray"]
    for value, code in enumerate(codes):
        binary = format(value, "0{}b".format(width))
        rows.append("{:>5}  {:>6}  {:>4}".format(value, binary, code))
    return "\n".join(rows)


def main():
