    for sample in samples:
        print("{!r} -> {}".format(sample, binary_to_gray(sample)))

    roundtrip = [gray_to_binary(binary_to_gray(s)) for s in samples]
    print("round trip:", roundtrip)

    print(format_table(3))

    codes = gray_sequence(4)
    steps = [differing_positions(a, b) for a, b in zip(codes, codes[1:])]
    changed = [positions[0] for positions in steps if len(positions) == 1]
    print("single-bit transitions:", len(changed), "of", len(steps))


